from pathlib import Path
import re

ROOT = Path(__file__).resolve().parents[1]

# 1) Existing-db self-healing for P4A additive CabinetConfig fields.
db_path = ROOT / 'backend/database.py'
db = db_path.read_text(encoding='utf-8')
old_cols = '''    new_columns = [\n        ("header_logo_offset_x", "FLOAT"),\n        ("header_logo_offset_y", "FLOAT"),\n        ("qr_code_offset_x", "FLOAT"),\n        ("qr_code_offset_y", "FLOAT"),\n    ]'''
new_cols = '''    new_columns = [\n        ("header_logo_offset_x", "FLOAT"),\n        ("header_logo_offset_y", "FLOAT"),\n        ("qr_code_offset_x", "FLOAT"),\n        ("qr_code_offset_y", "FLOAT"),\n        ("custom_specialty_fr", "VARCHAR(255)"),\n        ("custom_specialty_ar", "VARCHAR(255)"),\n        ("header_customized", "BOOLEAN DEFAULT FALSE"),\n    ]'''
if db.count(old_cols) != 1:
    raise SystemExit('database.py cabinet migration block mismatch')
db_path.write_text(db.replace(old_cols, new_cols, 1), encoding='utf-8')

# 2) Turn the P0 defect-capture contract into a regression guard for fixed P4A findings.
wf_path = ROOT / '.github/workflows/onboarding-settings-p0-cert.yml'
wf = wf_path.read_text(encoding='utf-8')
start = wf.index('      - name: Prove current onboarding/settings contracts\n')
end = wf.index('      - name:', start + 10)
new_step = '''      - name: Prove current onboarding/settings contracts\n        run: |\n          python - <<'PY'\n          import ast\n          import importlib.util\n          import pathlib\n          import sys\n          import types\n          from pydantic import ValidationError\n\n          root = pathlib.Path.cwd()\n          schemas_dir = root / "backend" / "schemas"\n          backend_pkg = types.ModuleType("backend")\n          backend_pkg.__path__ = [str(root / "backend")]\n          schemas_pkg = types.ModuleType("backend.schemas")\n          schemas_pkg.__path__ = [str(schemas_dir)]\n          sys.modules["backend"] = backend_pkg\n          sys.modules["backend.schemas"] = schemas_pkg\n\n          def load(name, path):\n              spec = importlib.util.spec_from_file_location(name, path)\n              module = importlib.util.module_from_spec(spec)\n              sys.modules[name] = module\n              spec.loader.exec_module(module)\n              return module\n\n          load("backend.schemas.base", schemas_dir / "base.py")\n          cabinet = load("backend.schemas.cabinet", schemas_dir / "cabinet.py")\n\n          # P4A regression guards: create/update use the same aliases/defaults.\n          create_by_name = cabinet.CabinetConfigCreate(nom_cabinet="P4", **{"if_": "12345678"})\n          assert create_by_name.if_ == "12345678"\n          assert "if_" in create_by_name.model_fields_set\n          assert create_by_name.model_dump(exclude_unset=True)["if_"] == "12345678"\n          assert cabinet.CabinetConfigCreate().selected_template == "swiss"\n          assert cabinet.CabinetConfigCreate().font_fr == "inter"\n          assert cabinet.CabinetConfigUpdate(custom_specialty_fr="Implantologie").custom_specialty_fr == "Implantologie"\n          try:\n              cabinet.CabinetConfigUpdate(logo_path="forbidden")\n          except ValidationError as exc:\n              assert any(err.get("type") == "extra_forbidden" for err in exc.errors())\n          else:\n              raise AssertionError("logo_path must stay upload-endpoint-only")\n\n          clinics_text = (root / "backend" / "routers" / "clinics.py").read_text(encoding="utf-8")\n          tree = ast.parse(clinics_text)\n          funcs = {node.name: node for node in tree.body if isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef))}\n          seg = lambda name: ast.get_source_segment(clinics_text, funcs[name]) or ""\n          create_src = seg("create_clinic")\n          update_src = seg("update_my_clinic")\n          get_src = seg("get_my_clinic")\n          logo_src = seg("upload_clinic_logo")\n          letter_src = seg("upload_clinic_letterhead")\n          assert "_require_setup_owner" in create_src\n          assert "db.query(models.User)" not in create_src\n          assert "_require_settings_write" in update_src\n          assert "_require_settings_write" in logo_src\n          assert "_require_settings_write" in letter_src\n          assert "models.CabinetConfig(" not in get_src\n          assert "db.commit()" not in get_src\n\n          store = (root / "frontend" / "src" / "features" / "admin" / "Settings" / "hooks" / "useSettingsStore.ts").read_text(encoding="utf-8")\n          assert "logo_path: _logoPath" in store\n          api_text = (root / "frontend" / "src" / "services" / "api.ts").read_text(encoding="utf-8")\n          assert "_offline: true" not in api_text\n          assert "offline-write-blocked" in api_text\n\n          # Remaining known findings stay explicit until their later lot fixes.\n          auth_schema = (root / "backend" / "schemas" / "auth.py").read_text(encoding="utf-8")\n          register_page = (root / "frontend" / "src" / "pages" / "RegisterPage.tsx").read_text(encoding="utf-8")\n          trial_page = (root / "frontend" / "src" / "pages" / "ActivateTrialPage.tsx").read_text(encoding="utf-8")\n          assert "PASSWORD_MIN_LENGTH = 8" in auth_schema\n          assert "minLength={4}" in register_page\n          assert "minLength={4}" in trial_page\n          app_text = (root / "frontend" / "src" / "App.tsx").read_text(encoding="utf-8")\n          assert "setIsInitialized(false)" in app_text\n          setup_text = (root / "frontend" / "src" / "features" / "admin" / "SetupWizard" / "SetupWizard.tsx").read_text(encoding="utf-8")\n          assert "localStorage.setItem('digitalcrown_theme', selectedTheme)" in setup_text\n          accounting = (root / "backend" / "services" / "generators" / "accounting_gen.py").read_text(encoding="utf-8")\n          assert "CabinetConfig.owner_id == user_id" in accounting\n          factory = (root / "backend" / "services" / "document_factory.py").read_text(encoding="utf-8")\n          models = (root / "backend" / "models.py").read_text(encoding="utf-8")\n          assert "models.Clinic" in factory\n          assert "class Clinic(" not in models\n          print("P0/P4A regression contract: PASS")\n          PY\n\n'''
wf_path.write_text(wf[:start] + new_step + wf[end:], encoding='utf-8')
print('P4A follow-up patch applied')
